        if ((Ast.IsExportSpecifier(usage.Parent) || (Ast.IsExportAssignment(usage.Parent) && usage.Parent.AsExportAssignment().IsExportEquals)))
        {
            return true;
        }
        if ((Ast.IsExportAssignment(usage) && usage.AsExportAssignment().IsExportEquals))
