                if (((n == stopAt) || (Ast.IsFunctionLike(n) && (((Ast.GetImmediatelyInvokedFunctionExpression(n) == null) || (((Ast.GetFunctionFlags(n) & FunctionFlags.AsyncGenerator) != 0)))))))
                {
                    return false;
                }
