        if ((symbol.CheckFlags & CheckFlags.Mapped) != 0)
            return getTypeOfMappedSymbol(symbol);
        if ((symbol.CheckFlags & CheckFlags.ReverseMapped) != 0)
            return getTypeOfReverseMappedSymbol(symbol);
